-- =============================================================================================
-- BizApps Tasks v1.12.x -- Metadata_Sync (approval reassignment setting)
-- =============================================================================================
-- Generated by `mj sync push --dir metadata --ci` (MJ CLI 6.2.1) against a database built from
-- migrations ONLY: MJ core v6.2.1, then bizapps-common, -accounting, -orders, -contracts and -sales
-- at their released `main`, then this app's migrations at `next`.
--
-- CREATED: the Tasks application setting ApprovalReassignRoles, empty by default (bc-aidp-next-
-- golive#389). Empty switches the role rule off, so approval assignments move as before.
--
-- CREATE-ONLY: the create is guarded on its ID or (ApplicationID, Name), and the push log's update
-- branch is cut, so a host that already set its roles keeps them. The application resolves by Name.
--
-- NOT INCLUDED: the push also creates the ML training pipelines, ML model, scoring binding, record
-- process and scheduled job under metadata/ml-*, record-processes. No earlier Tasks seed ships
-- them, and this one does not change that.
--
-- TRANSFORMS: `[${mjSchema}].` -> `[${mjSchema}].`; string values untouched. Idempotent.
-- =============================================================================================

-- Save MJ: Application Settings (core SP call only)
DECLARE @ID_372ce7d1ab33 UNIQUEIDENTIFIER,
@ApplicationID_372ce7d1ab33 UNIQUEIDENTIFIER,
@Name_372ce7d1ab33 NVARCHAR(100),
@Value_372ce7d1ab33 NVARCHAR(MAX),
@Comments_372ce7d1ab33 NVARCHAR(MAX)
SET
  @ID_372ce7d1ab33 = 'CBF531C2-4DBE-4F63-9CFB-C3266835AD6E'
SET
  @ApplicationID_372ce7d1ab33 = (
    SELECT
      [ID]
    FROM
      [${mjSchema}].[Application]
    WHERE
      LOWER([Name]) = LOWER(N'Tasks')
  )
SET
  @Name_372ce7d1ab33 = N'ApprovalReassignRoles'
SET
  @Value_372ce7d1ab33 = N''
SET
  @Comments_372ce7d1ab33 = N'Comma-separated NAMES of the MJ roles whose holders may change who an approval task (a task whose type has IsApproval set) is assigned to, or remove its assignee (bc-aidp-next-golive#389). Names match trimmed and case-insensitively; a name that is not a role matches nobody and is logged. Nobody may reassign an approval to themselves, whatever their role. Creating assignments is not checked, so workflow routing is unaffected. Empty, the default, switches the role rule off, so assignments move as before; the self-assignment refusal still applies.'
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[ApplicationSetting]
               WHERE [ID] = @ID_372ce7d1ab33
                  OR ([ApplicationID] = @ApplicationID_372ce7d1ab33 AND [Name] = @Name_372ce7d1ab33))
BEGIN
EXEC [${mjSchema}].spCreateApplicationSetting @ID = @ID_372ce7d1ab33,
  @ApplicationID = @ApplicationID_372ce7d1ab33,
  @Name = @Name_372ce7d1ab33,
  @Value = @Value_372ce7d1ab33,
  @Comments = @Comments_372ce7d1ab33
END;

GO
